WITH kept AS (SELECT s.* FROM accounts s WHERE EXISTS (SELECT 1 FROM transactions ch WHERE ch.account_id = s.id AND ch.txn_time <= s.opened_date)) SELECT CASE WHEN balance >= 62000 THEN 'PREMIUM' ELSE 'STANDARD' END AS balance_tier, SIZE(COLLECT_SET(account_type)) AS num_account_types, SORT_ARRAY(COLLECT_SET(status)) AS status_list, COUNT(*) FILTER (WHERE status = 'CLOSED') AS closed_rows FROM kept GROUP BY CASE WHEN balance >= 62000 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING num_account_types >= 1;
